#!/usr/bin/env bash
# Remove namespaces generated by a Flux ResourceSet without touching shared infrastructure.
# Usage: resourceset-down.sh RESOURCESET INPUTS_FILE NAMESPACE [NAMESPACE ...]

set -eo pipefail

if [ "$#" -lt 3 ]; then
  echo "usage: $0 RESOURCESET INPUTS_FILE NAMESPACE [NAMESPACE ...]" >&2
  exit 2
fi

RESOURCESET="$1"
INPUTS_FILE="$2"
shift 2
NAMESPACES=("$@")
FLUX_NS="${FLUX_NS:-flux-system}"
FAILED=0

clear_namespaced_finalizers() {
  local ns="$1"
  local resource object

  while IFS= read -r resource; do
    while IFS= read -r object; do
      [ -n "${object}" ] || continue
      kubectl patch "${object}" -n "${ns}" --type merge \
        -p '{"metadata":{"finalizers":[]}}' >/dev/null 2>&1 || true
    done < <(kubectl get "${resource}" -n "${ns}" -o name --ignore-not-found 2>/dev/null || true)
  done < <(kubectl api-resources --verbs=list --namespaced -o name 2>/dev/null)
}

force_finalize_namespace() {
  local ns="$1"
  local attempt

  for attempt in $(seq 1 10); do
    if ! kubectl get namespace "${ns}" >/dev/null 2>&1; then
      return 0
    fi

    if kubectl get namespace "${ns}" -o json 2>/dev/null |
      python3 -c 'import json,sys; obj=json.load(sys.stdin); obj["spec"]["finalizers"]=[]; json.dump(obj,sys.stdout)' |
      kubectl replace --raw "/api/v1/namespaces/${ns}/finalize" -f - >/dev/null 2>&1; then
      echo "    ${ns}: force-finalization requested (${attempt}/10)."
    else
      echo "    WARNING: force-finalization request failed for ${ns} (${attempt}/10)."
    fi
    sleep 2
  done

  return 1
}

echo "==> Saving ResourceSet inputs for later restoration..."
CURRENT_INPUTS=$(kubectl get resourceset "${RESOURCESET}" -n "${FLUX_NS}" \
  -o jsonpath='{.spec.inputs}' 2>/dev/null)
if [ -n "${CURRENT_INPUTS}" ] && [ "${CURRENT_INPUTS}" != "[]" ]; then
  printf '%s' "${CURRENT_INPUTS}" > "${INPUTS_FILE}"
elif [ ! -s "${INPUTS_FILE}" ]; then
  printf '%s' "${CURRENT_INPUTS}" > "${INPUTS_FILE}"
fi

# Emptying inputs alone does not stop recreation, and never did. flux-operator
# renders spec.resources with `Option("missingkey=error")`, and BuildResourceSet
# treats an empty input list as "render ONCE against a nil map" rather than
# "render nothing", so the ResourceSet does not go quiet — it goes Stalled with
# `map has no entry for key "tenant"`. (The deploy-nothing-and-GC behaviour is
# real but the controller gates it on `len(obj.Spec.InputsFrom) > 0`.)
#
# The supported off-switch is the reconcile annotation, checked by
# obj.IsDisabled() before the build. Set it FIRST so the controller is already
# skipping this object by the time the inputs are cleared. Inputs are still
# emptied afterwards so `demo-*-down` leaves the same observable spec.inputs
# state the existing checks look for.
echo "==> Disabling reconciliation for ResourceSet '${RESOURCESET}' (stops recreation)..."
kubectl annotate resourceset "${RESOURCESET}" -n "${FLUX_NS}" \
  fluxcd.controlplane.io/reconcile=disabled --overwrite

echo "==> Patching ResourceSet '${RESOURCESET}' to empty inputs..."
kubectl patch resourceset "${RESOURCESET}" -n "${FLUX_NS}" \
  --type merge -p '{"spec":{"inputs":[]}}'
kubectl annotate resourceset "${RESOURCESET}" -n "${FLUX_NS}" \
  reconcile.fluxcd.io/requestedAt="$(date -u +%Y-%m-%dT%H:%M:%SZ)" --overwrite

sleep 2

for ns in "${NAMESPACES[@]}"; do
  if ! kubectl get namespace "${ns}" &>/dev/null; then
    echo "==> Namespace '${ns}' does not exist — skipping."
    continue
  fi

  echo "==> Clearing all namespaced finalizers in ${ns}..."
  clear_namespaced_finalizers "${ns}"

  echo "==> Deleting namespace '${ns}'..."
  if ! kubectl delete namespace "${ns}" --timeout=30s; then
    echo "    WARNING: namespace delete timed out or failed for ${ns}."
  fi
done

for ns in "${NAMESPACES[@]}"; do
  for i in $(seq 1 15); do
    kubectl get namespace "${ns}" &>/dev/null || break
    if [ "$i" -eq 5 ] || [ "$i" -eq 10 ]; then
      clear_namespaced_finalizers "${ns}"
    fi
    sleep 2
  done

  if kubectl get namespace "${ns}" &>/dev/null; then
    echo "    ${ns}: still Terminating — force-finalizing via API..."
    clear_namespaced_finalizers "${ns}"
    force_finalize_namespace "${ns}" || \
      echo "    WARNING: ${ns} still Terminating after force-finalize retries."
  fi

  if kubectl get namespace "${ns}" &>/dev/null; then
    echo "    WARNING: ${ns} still Terminating after force-finalize."
    FAILED=1
  else
    echo "    ${ns}: fully deleted."
  fi
done

if [ "${FAILED}" -ne 0 ]; then
  echo "WARNING: one or more namespaces remain."
  exit 1
fi

echo "==> ResourceSet '${RESOURCESET}' namespaces removed."
echo "    ResourceSet inputs saved to ${INPUTS_FILE}"
